    sourceLocation: "第二编·第九章·第三节“自由主义作家文艺观及两大文艺思潮的对立”",
    sourcePages: ["扫描件PDF第218—225页", "教材书内页第201—208页"],
    sourceStatus: "教材正文已核",
    sourceNote:
      "自由主义共同立场、新月派、性灵文学、京派论争及印象批评均按本节正文核校；评价保留教材的历史语境与双面分析。",
