export function getSourceFaithfulStudyCard(
  subjectId: "ancient" | "modern",
  partTitle: string,
  chapterTitle: string,
  topic: string,
) {
  return sourceFaithfulCards[
    sourceKey(subjectId, partTitle, chapterTitle, topic)
  ];
}
